// modules/library/components/AuthorForm.js
import { useEffect, useState, useCallback } from "react";
import { authorApi } from "../api/authorApi";
import { useParams, useNavigate } from "react-router-dom";

const COUNTRIES = [
  "Ethiopia", "American", "British", "Canadian", "French", "German",
  "Japanese", "Chinese", "Indian", "Australian", "Spanish",
  "Italian", "Russian", "Brazilian", "Mexican", "Other"
];

const INITIAL_FORM_STATE = {
  first_name: "",
  last_name: "",
  biography: "",
  nationality: "",
  date_of_birth: "",
  website: ""
};

export default function AuthorForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState(INITIAL_FORM_STATE);

  const isCreateMode = method === "create";
  const isEditMode = method === "edit";

  const fetchAuthor = useCallback(async () => {
    if (!isEditMode) return;

    setIsLoading(true);
    try {
      const response = await authorApi.get(`/${id}`);
      setFormData(response.data);
    } catch (error) {
      console.error("Failed to fetch author:", error);
    } finally {
      setIsLoading(false);
    }
  }, [id, isEditMode]);

  useEffect(() => {
    fetchAuthor();
  }, [fetchAuthor]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const apiCall = isCreateMode
        ? authorApi.post("/", formData)
        : authorApi.put(`/${id}`, formData);

      await apiCall;

      // Success feedback before navigation
      setTimeout(() => {
        navigate("/library/author");
      }, 800);

    } catch (error) {
      console.error("Form submission failed:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleResetForm = () => {
    if (!isEditMode) {
      setFormData(INITIAL_FORM_STATE);
    }
  };

  const handleBack = () => {
    navigate("/library/author");
  };

  if (isLoading && isEditMode) {
    return (
      <div className="flex justify-center items-center min-h-screen">
        <div className="text-center">
          <div className="spinner-border text-primary animate-spin border-4 border-t-transparent rounded-full w-12 h-12" role="status">
            <span className="sr-only">Loading...</span>
          </div>
          <p className="mt-4 text-gray-600">Loading author details...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header Section */}
      <header className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center py-6">
            <div className="flex items-center space-x-3 mb-4 sm:mb-0">
              <div className="bg-indigo-100 p-3 rounded-lg">
                <i className={`fas ${isCreateMode ? "fa-user-plus" : "fa-user-edit"} text-indigo-600 text-xl`}></i>
              </div>
              <div>
                <h1 className="text-2xl font-bold text-gray-900">
                  {isCreateMode ? "Add New Author" : "Edit Author"}
                </h1>
                <nav className="flex items-center space-x-2 text-sm text-gray-500 mt-1">
                  <a href="/" className="hover:text-indigo-600 transition-colors">
                    <i className="fas fa-home mr-1"></i> Home
                  </a>
                  <span className="text-gray-300">/</span>
                  <a href="/library" className="hover:text-indigo-600 transition-colors">
                    <i className="fas fa-book mr-1"></i> Library
                  </a>
                  <span className="text-gray-300">/</span>
                  <a href="/library/author" className="hover:text-indigo-600 transition-colors">
                    <i className="fas fa-users mr-1"></i> Authors
                  </a>
                  <span className="text-gray-300">/</span>
                  <span className="font-medium">
                    <i className={`fas ${isCreateMode ? "fa-plus-circle" : "fa-edit"} mr-1`}></i>
                    {isCreateMode ? "Add Author" : "Edit Author"}
                  </span>
                </nav>
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200">
          {/* Card Header */}
          <div className="px-8 py-6 border-b border-gray-100 bg-gradient-to-r from-gray-50 to-white">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="bg-blue-100 p-2 rounded-lg">
                  <i className="fas fa-id-card text-blue-600"></i>
                </div>
                <div>
                  <h2 className="text-xl font-semibold text-gray-800">Author Details</h2>
                  <p className="text-gray-500 mt-1">
                    {isCreateMode
                      ? "Fill in the details to add a new author"
                      : "Update the author information below"}
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="px-8 py-6">
            <div className="space-y-6">
              {/* Name Fields */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <FormField
                  label="First Name"
                  name="first_name"
                  value={formData.first_name}
                  onChange={handleInputChange}
                  placeholder="e.g., John"
                  required
                  icon="signature"
                  loading={isLoading}
                  description="Author's first name (required)"
                />

                <FormField
                  label="Last Name"
                  name="last_name"
                  value={formData.last_name}
                  onChange={handleInputChange}
                  placeholder="e.g., Doe"
                  required
                  icon="signature"
                  loading={isLoading}
                  description="Author's last name (required)"
                />
              </div>

              {/* Nationality & Date of Birth */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="block text-sm font-medium text-gray-700">
                    <i className="fas fa-flag mr-2 text-blue-500"></i>
                    Nationality
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                      <i className="fas fa-globe-americas text-gray-400"></i>
                    </div>
                    <select
                      className="block w-full pl-10 pr-3 py-3 text-base border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
                      name="nationality"
                      value={formData.nationality}
                      onChange={handleInputChange}
                      disabled={isLoading}
                    >
                      <option value="">Select Nationality</option>
                      {COUNTRIES.map(country => (
                        <option key={country} value={country}>{country}</option>
                      ))}
                    </select>
                  </div>
                  <p className="text-sm text-gray-500">
                    <i className="fas fa-info-circle mr-1"></i>
                    Select the author's nationality
                  </p>
                </div>

                <FormField
                  type="date"
                  label="Date of Birth"
                  name="date_of_birth"
                  value={formData.date_of_birth || ""}
                  onChange={handleInputChange}
                  icon="birthday-cake"
                  loading={isLoading}
                  description="Author's birth date (YYYY-MM-DD)"
                />
              </div>

              {/* Website Field */}
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  <i className="fas fa-globe mr-2 text-green-500"></i>
                  Website URL
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <i className="fas fa-link text-gray-400"></i>
                  </div>
                  <input
                    type="url"
                    className="block w-full pl-10 pr-12 py-3 text-base border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition-colors"
                    name="website"
                    value={formData.website}
                    onChange={handleInputChange}
                    placeholder="https://www.author-website.com"
                    disabled={isLoading}
                  />
                  {formData.website && (
                    <div className="absolute inset-y-0 right-0 flex items-center pr-3">
                      <a
                        href={formData.website}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-green-600 hover:text-green-800 transition-colors"
                      >
                        <i className="fas fa-external-link-alt"></i>
                      </a>
                    </div>
                  )}
                </div>
                <p className="text-sm text-gray-500">
                  <i className="fas fa-info-circle mr-1"></i>
                  Author's official website (include https://)
                </p>
              </div>

              {/* Biography Field */}
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  <i className="fas fa-book-open mr-2 text-amber-500"></i>
                  Biography
                </label>
                <div className="relative">
                  <textarea
                    className="block w-full px-4 py-3 text-base border border-gray-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-amber-500 transition-colors resize-none"
                    rows="5"
                    name="biography"
                    value={formData.biography}
                    onChange={handleInputChange}
                    placeholder="Write about the author's life, achievements, and notable works..."
                    disabled={isLoading}
                  />
                  <div className="absolute bottom-2 right-2 bg-white px-2 py-1 rounded text-sm text-gray-500">
                    {formData.biography.length} characters
                  </div>
                </div>
                <div className="flex justify-between items-center text-sm text-gray-500">
                  <p>
                    <i className="fas fa-info-circle mr-1"></i>
                    Brief biography about the author (optional)
                  </p>
                  <p>
                    <i className="fas fa-lightbulb mr-1"></i>
                    Tip: Include notable works and awards
                  </p>
                </div>
              </div>

              {/* Edit Mode Notification */}
              {isEditMode && (
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                  <div className="flex items-start">
                    <div className="flex-shrink-0">
                      <i className="fas fa-info-circle text-blue-500 text-xl mt-1"></i>
                    </div>
                    <div className="ml-3">
                      <h3 className="text-sm font-medium text-blue-800">Editing Mode</h3>
                      <div className="mt-2 text-sm text-blue-700">
                        <p className="mb-1">
                          You are editing author <strong>{formData.first_name} {formData.last_name}</strong>
                        </p>
                        <p>
                          <i className="fas fa-id-card mr-1"></i>
                          Author ID: <code className="bg-blue-100 px-2 py-1 rounded">{id}</code>
                        </p>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Form Actions */}
            <div className="mt-8 pt-6 border-t border-gray-200">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <button
                  type="button"
                  onClick={handleBack}
                  disabled={isLoading}
                  className="inline-flex justify-center items-center px-6 py-3 border border-gray-300 text-base font-medium rounded-lg text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <i className="fas fa-arrow-left mr-3"></i>
                  Back to List
                </button>

                <button
                  type="button"
                  onClick={handleResetForm}
                  disabled={isLoading || isEditMode}
                  className="inline-flex justify-center items-center px-6 py-3 border border-amber-300 text-base font-medium rounded-lg text-amber-700 bg-white hover:bg-amber-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-amber-500 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <i className="fas fa-redo mr-3"></i>
                  Reset Form
                </button>

                <button
                  type="submit"
                  disabled={isLoading}
                  className="inline-flex justify-center items-center px-6 py-3 border border-transparent text-base font-medium rounded-lg text-white bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isLoading ? (
                    <>
                      <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-3"></div>
                      Processing...
                    </>
                  ) : (
                    <>
                      <i className="fas fa-save mr-3"></i>
                      {isCreateMode ? "Create Author" : "Update Author"}
                    </>
                  )}
                </button>
              </div>
            </div>
          </form>
        </div>

        {/* Info Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-8">
          <InfoCard
            title="Need Help?"
            subtitle="Contact Support"
            icon="question-circle"
            color="blue"
            description="Fill all required fields marked with *"
          />
          <InfoCard
            title="Quick Tips"
            subtitle="Best Practices"
            icon="check-circle"
            color="green"
            description="Provide accurate and complete information"
          />
        </div>
      </main>
    </div>
  );
}

// Helper Components
function FormField({
  type = "text",
  label,
  name,
  value,
  onChange,
  placeholder,
  required = false,
  icon,
  loading,
  description
}) {
  return (
    <div className="space-y-2">
      <label className="block text-sm font-medium text-gray-700">
        <i className="fas fa-user-circle mr-2 text-blue-500"></i>
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <i className={`fas fa-${icon} text-gray-400`}></i>
        </div>
        <input
          type={type}
          className="block w-full pl-10 pr-3 py-3 text-base border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
          name={name}
          value={value}
          onChange={onChange}
          placeholder={placeholder}
          required={required}
          disabled={loading}
        />
      </div>
      <p className="text-sm text-gray-500">
        <i className="fas fa-info-circle mr-1"></i>
        {description}
      </p>
    </div>
  );
}

function InfoCard({ title, subtitle, icon, color, description }) {
  const colorClasses = {
    blue: "from-blue-500 to-blue-600",
    green: "from-emerald-500 to-green-600"
  };

  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden">
      <div className={`bg-gradient-to-r ${colorClasses[color]} px-6 py-4`}>
        <div className="flex items-center">
          <div className="bg-white bg-opacity-20 p-3 rounded-lg">
            <i className={`fas fa-${icon} text-white text-xl`}></i>
          </div>
          <div className="ml-4">
            <h3 className="text-lg font-semibold text-white">{title}</h3>
            <p className="text-blue-100">{subtitle}</p>
          </div>
        </div>
      </div>
      <div className="px-6 py-4">
        <div className="w-full bg-gray-200 rounded-full h-2 mb-3">
          <div className="bg-gray-600 h-2 rounded-full w-full"></div>
        </div>
        <p className="text-sm text-gray-600">{description}</p>
      </div>
    </div>
  );
}
